class OrderBook {
  constructor(stock) {
    this.stock = stock;
    this.orders = [];
    this.nextId = 1000;
  }

  place(cart, today) {
    if (cart.isEmpty()) {
      throw new ShopError('empty_cart', 'cart is empty');
    }
    const items = cart.items();
    const reserved = [];
    try {
      for (const line of items) {
        this.stock.reserve(line.sku, line.qty);
        reserved.push({ sku: line.sku, qty: line.qty });
      }
    } catch (error) {
      for (const { sku, qty } of reserved) {
        this.stock.release(sku, qty);
      }
      throw error;
    }

    const order = {
      id: `O-${this.nextId++}`,
      date: today,
      items,
      currency: cart.currency,
      country: cart.country,
      coupons: cart.coupons.map((c) => c.code),
      ...price,
      shipping: shippingCost(cart),
      status: 'placed',
      history: [{ status: 'placed', date: today }],
    };

    this.orders.push(order);
    return order;
  }

  cancel(id, today) {
    const order = this.transition(id, 'cancelled', today);
    for (const { sku, qty } of order.items) {
      this.stock.release(sku, qty);
    }
    return order;
  }

  transition(id, status, today) {
    const order = this.get(id);
    if (order.status === 'cancelled') {
      throw new ShopError('order_cancelled', 'order is already cancelled');
    }
    order.status = status;
    order.history.push({ status, date: today });
    return order;
  }

  get(id) {
    return this.orders.find((o) => o.id === id);
  }
}
